pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(c));
        vm.assume(caller != c.owner());
        vm.prank(c.owner());
        c.transferOwnership(caller);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}
        assert(c.owner() == newOwner);
    }
}
